import random

GROUP = "number_theory"
SKILL = "counting"

def generate(seed):
    rng = random.Random(seed)
    primes = sorted(rng.sample([2, 3, 5, 7, 11, 13, 17, 19], 4))  # select 4 distinct primes
    e = rng.randint(50, 150)  # e is the exponent in the prime factorization

    # Calculate the number of integers less than or equal to e that are not divisible by any of the chosen primes.
    # This is the total number of integers minus the number that are divisible by at least one of the primes.
    total = e
    for prime in primes:
        total -= e // prime
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            total += e // (primes[i] * primes[j])
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            for k in range(j + 1, len(primes)):
                total -= e // (primes[i] * primes[j] * primes[k])
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            for k in range(j + 1, len(primes)):
                for l in range(k + 1, len(primes)):
                    total += e // (primes[i] * primes[j] * primes[k] * primes[l])

    # Independent route: test every integer in the range [1, e] to see if it is divisible by any of the chosen primes.
    check = sum(1 for k in range(1, e + 1) if all(k % prime != 0 for prime in primes))
    assert total == check, f"total={total} check={check}"

    problem = (
        f"How many integers less than or equal to {e} are not divisible by any of the primes {primes}? "
        f"State only the integer."
    )
    return problem, str(check)

