def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(1000, 2000)
    primes = sorted(rng.sample([2, 3, 5, 7, 11, 13, 17, 19, 23], 3))

    # Define a function to check if a number has a specific property (e.g., not divisible by any of the primes)
    def has_property(num):
        return not any(num % p == 0 for p in primes)

    # Count numbers from 1 to n that have the specific property
    count = sum(1 for k in range(1, n + 1) if has_property(k))

    # Independent route: count the numbers by checking each number individually
    check = 0
    for k in range(1, n + 1):
        if has_property(k):
            check += 1
    assert count == check, f"count={count} check={check}"

    problem = (
        f"How many integers k exist such that 1 <= k <= {n} and k is not divisible "
        f"by any of {primes[0]}, {primes[1]} and {primes[2]}? State only the integer."
    )
    return problem, str(count)

