            for j in range(i + 1, len(primes)):
                for k in range(j + 1, len(primes)):
                    count += (n // (primes[i] * primes[j] * primes[k]))
        return count

    # Count numbers from 1 to n that are divisible by any of the primes
    count_divisible = count_divisible_by_any_of_primes(n, primes)

    # Independent route: count the numbers by checking each number individually
    check = 0
    for k in range(1, n + 1):
        if any(k % p == 0 for p in primes):
            check += 1
    assert count_divisible == check, f"count_divisible={check} check={count_divisible}"

    problem = (
        f"How many integers k exist such that 1 <= k <= {n} and k is divisible "
